import{z as A,x as s,o as e,c as B,q as l,j as i,D as t,d as r,s as E,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"远期起始与 cliquet","description":"","frontmatter":{"title":"远期起始与 cliquet","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cliquet-forward-start.md","filePath":"quant/cliquet-forward-start.md","lastUpdated":1791063341000}'),p={name:"quant/cliquet-forward-start.md"};function c(u,a,d,q,_,h){const o=s("Mermaid");return e(),B("div",null,[a[2]||(a[2]=l('<h1 id="远期起始与-cliquet" tabindex="-1">远期起始与 cliquet <a class="header-anchor" href="#远期起始与-cliquet" aria-label="Permalink to &quot;远期起始与 cliquet&quot;">​</a></h1><div class="epigraph"><p>远期起始期权在未来某日才把执行价钉成当时的现价；cliquet 是一串重置的远期起始，局部收益被封顶封底后再累加。</p><footer>—— Rubinstein, Pay Now, Choose Later, Risk, 1991；cliquet 结构见结构产品实务与 Wilmott 对重置期权的讨论</footer></div><p><a href="/quant/quanto-options">上一课</a>把外汇计价加进多资产。本课回到单资产，但把<strong>执行价的时钟</strong>推迟：远期起始在 \\(t_0\\gt 0\\) 才令 \\(K=S_{t_0}\\)，cliquet 把区间收益 \\(\\bigl(S_{t_{i+1}}/S_{t_i}-1\\bigr)\\) 逐段封顶，再累加或复合。缺口是前向微笑——ATM 香草曲面不够，因为每段重置都在未来的 ATM 上取值。后课 autocallable 会把重置与障碍耦合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通香草的 \\(K\\) 在 \\(t=0\\) 已知，Vega 落在当前曲面的一个点。远期起始的价值在 GBM 下可写成折现的 ATM 公式，只依赖从 \\(t_0\\) 到 \\(T\\) 的远期波动；有微笑与期限结构时，需要的是<strong>未来那一天的 ATM 已实现隐波</strong>，也就是远期波动，而不是把 \\(T\\) 到期的今日 ATM 拿来用。Cliquet 把许多段短到期的远期起始串起来，再对每段施加 cap/floor，于是对远期偏斜与远期波动的凸性极度敏感。</p><p><span class="marginnote">术语翻译：远期起始就是「先成交、执行价以后才定」的期权——今天付权利金，三个月后才把执行价钉成那天的现价。直觉类比：预约一年后的体检，价格按体检当天的挂牌价结算；你赌的不是今天的价格，而是「到时候的价格相对当天的位置」。</span></p><p>卖方若用今天的短到期 ATM 去加总，会漏掉 vol-of-vol：未来 ATM 会动，封顶使每段收益的分布被截断，凸性符号与香草相反。2000 年代欧洲 cliquet 的亏损，多来自用局部波动或扁平远期 vol 低估了这种凸性。</p>',7)),(e(),i(n,null,{default:t(()=>[E(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20LR%0A%20%20T0%5B%22%E4%BB%8A%E6%97%A5%20t%3D0%20%E6%94%AF%E4%BB%98%E6%9D%83%E5%88%A9%E9%87%91%22%5D%20--%3E%20R1%5B%22%E9%87%8D%E7%BD%AE%E6%97%A5%20t1%3A%20%E6%89%A7%E8%A1%8C%E4%BB%B7%20K1%20%3D%20S(t1)%22%5D%0A%20%20R1%20--%3E%20S1%5B%22%E6%AE%B51%E6%94%B6%E7%9B%8A%20%3D%20S(t2)%2FS(t1)%20-%201%22%5D%0A%20%20S1%20--%3E%20C1%5B%22%E5%B0%81%E9%A1%B6%205%25%20%2F%20%E5%B0%81%E5%BA%95%200%25%22%5D%0A%20%20C1%20--%3E%20ACC%5B%22%E7%B4%AF%E5%8A%A0%E8%BF%9B%E7%A5%A8%E6%81%AF%22%5D%0A%20%20ACC%20--%3E%20R2%5B%22%E9%87%8D%E7%BD%AE%E6%97%A5%20t2%3A%20K2%20%3D%20S(t2)%22%5D%0A%20%20R2%20--%3E%20S2%5B%22%E6%AE%B52%E6%94%B6%E7%9B%8A%20%E5%90%8C%E4%B8%80%E8%A7%84%E5%88%99%22%5D%0A%20%20S2%20--%3E%20C2%5B%22%E5%86%8D%E5%B0%81%E9%A1%B6%E5%B0%81%E5%BA%95%22%5D%0A%20%20C2%20--%3E%20ACC%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="一段远期起始不是「到期更晚的-atm」" tabindex="-1">一段远期起始不是「到期更晚的 ATM」 <a class="header-anchor" href="#一段远期起始不是「到期更晚的-atm」" aria-label="Permalink to &quot;一段远期起始不是「到期更晚的 ATM」&quot;">​</a></h3><p>记区间 \\([t,T]\\)。远期起始看涨在 \\(t\\) 变成执行价 \\(S_t\\) 的 ATM（或 \\(\\alpha S_t\\) 的百分比执行价）。其 \\(t=0\\) 的价格依赖 \\(t\\) 到 \\(T\\) 的远期方差。今日交易的 \\(T\\) 到期 ATM 含 \\(0\\) 到 \\(T\\) 的整段方差，减不干净 \\(0\\) 到 \\(t\\) 的那一段与相关。必须用方差互换或日历结构抽出远期方差，见 <a href="/quant/variance-swap-vix">方差互换</a> 与 <a href="/quant/vol-surface">隐波曲面</a>。</p><p><span class="marginnote">百分比执行价 \\(\\alpha\\neq1\\) 的远期起始，吃的是未来微笑上 \\(\\alpha\\) 那一点，不是未来 ATM。局部 cap 为 5% 的月度 cliquet，对每个月的上侧偏斜一阶敏感。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>GBM：远期起始有闭式，cliquet 在独立对数正态段下可把每段当封顶封底的数字组合。有微笑：局部波动能重现今日香草，但远期微笑往往过扁，cliquet 会系统性偏便宜或偏贵，应对照 <a href="/quant/heston">Heston</a> / <a href="/quant/sabr">SABR</a> 的远期微笑。数值上用带重置的 <a href="/quant/mc-pricing">蒙特卡洛</a>，状态含当前现价与已累计票息；不要对整段路径只看 \\(S_T\\)。</p><p>对冲：逐段的远期 Vega、对 cap 水平的数字风险、以及重置日附近的 Gamma。日历对冲用香草日历价差去逼近远期方差，残差是偏斜与 vol-of-vol。</p><p><span class="marginnote">数字实例：月度 cliquet、cap 5%、floor 0%。某月标的涨 12%，这一段只记 5%；下月跌 3%，记 0%——两个月合计 +5%，而不是 +9% 或 -3%。卖方等于每个月把上行超过 5% 的部分卖成了数字期权，大涨行情里票息「涨不动」，这正是封顶的代价。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重置把路径切成相邻收益。每段的封顶等价于卖出该段上侧数字/看涨价差，封底等价于买入下侧保护。整份 cliquet 于是是一串远期起始的香草与数字。定价核关心的是每段收益的风险中性分布，也就是远期微笑。局部波动沿今日密度演化，对未来偏斜的预测往往不足，这正是 cliquet 成为模型试金石的原因——不是因为结构「更奇异」，而是因为它把曲面的时间演化暴露出来。</p><p><span class="marginnote">直觉类比：远期微笑像「下周一的天气预报」——你需要的不是今天对下周一的预报值，而是到下周一时、当天的天气分布。用今天曲面外推，等于假设「预报本身不变」，漏掉的正是 vol-of-vol：波动率自己也是会波动的。</span></p>',10)),(e(),i(n,null,{default:t(()=>[E(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22%E8%BF%9C%E6%9C%9F%E8%B5%B7%E5%A7%8B%20%E6%9C%AA%E6%9D%A5%E9%92%89%20K%22%5D%20--%3E%20FV%5B%22%E4%BE%9D%E8%B5%96%E8%BF%9C%E6%9C%9F%E6%96%B9%E5%B7%AE%22%5D%0A%20%20Cli%5B%22cliquet%20%E5%A4%9A%E6%AE%B5%E9%87%8D%E7%BD%AE%22%5D%20--%3E%20Cap%5B%22%E6%AF%8F%E6%AE%B5%20cap%20%E4%B8%8E%20floor%22%5D%0A%20%20Cap%20--%3E%20FS%0A%20%20Cap%20--%3E%20Skew%5B%22%E8%BF%9C%E6%9C%9F%E5%81%8F%E6%96%9C%E4%B8%8E%20vol-of-vol%22%5D%0A%20%20FV%20--%3E%20Price%5B%22%E4%B8%8D%E8%83%BD%E7%94%A8%E4%BB%8A%E6%97%A5%E9%95%BF%E5%88%B0%E6%9C%9F%20ATM%20%E4%BB%A3%E6%9B%BF%22%5D%0A%20%20Skew%20--%3E%20Price%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>段与段之间的相关（波动聚集）会改变累计票息的分布，独立段假设会错。离散分红、停牌、涨跌停让「区间收益」的定义依赖合同。权益连结年金与零售 cliquet 还叠加死亡率与退保，本课只写市场风险那一块。</p><p>不要把 cliquet 当「每月锁定收益的理财」。cap 已经把上侧卖掉，floor 的成本在票息里；模型若低估远期偏斜，卖掉的上侧会系统性便宜。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>远期起始吃的是未来 ATM（或百分比执行价）的远期波动，不是今日长到期 ATM。</li><li>Cliquet 是带 cap/floor 的重置串，对远期微笑与 vol-of-vol 敏感，局部波动常不够。</li><li>对冲要拆成远期方差、数字与重置日 Gamma。</li><li>出处：Rubinstein, <em>Risk</em>, 1991；远期微笑与 cliquet 的模型敏感见 Bergomi 对远期方差的论述。</li></ul>',5))])}const m=A(p,[["render",c]]);export{f as __pageData,m as default};
